def db():
    conn = sqlite3.connect(DB_NAME, timeout=30)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA foreign_keys=ON")
    # Return named SQLite rows so database column order can never break the app.
    conn.row_factory = sqlite3.Row
    return conn


def hash_password(password, salt=None):
    salt = salt or secrets.token_hex(16)
    digest = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt.encode("utf-8"), 120_000).hex()
    return f"pbkdf2${salt}${digest}"


def verify_password(stored, password):
    if stored.startswith("pbkdf2$"):
        try:
            _, salt, digest = stored.split("$", 2)
            candidate = hash_password(password, salt).split("$", 2)[2]
            return secrets.compare_digest(candidate, digest), True
        except Exception:
            return False, True
    return secrets.compare_digest(stored, password), False


ETHIOPIA_TZ = ZoneInfo("Africa/Addis_Ababa")


def now_eth():
    """Return the current real local time in Addis Ababa, independent of Streamlit Cloud server timezone."""
    return datetime.now(ETHIOPIA_TZ)


def get_ethiopian_clock(dt=None):
    dt = dt or now_eth()
    # Always normalize an incoming naive/other-zone datetime to Addis Ababa.
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=ETHIOPIA_TZ)
    else:
        dt = dt.astimezone(ETHIOPIA_TZ)
    h = dt.hour
    m = dt.minute
    s = dt.second
    eth_h = (h - 6) % 12
    if eth_h == 0:
        eth_h = 12
    if 6 <= h < 12:
        period = "ጠዋት"
    elif 12 <= h < 18:
        period = "ከሰዓት"
    else:
        period = "ማታ"
    return f"{eth_h}:{m:02d}:{s:02d} {period}"


def get_ethiopian_time():
    now = now_eth()
    return f"{now:%Y-%m-%d} {get_ethiopian_clock(now)}"


def parse_hm(value):
    h, m = map(int, value.split(":"))
    return h * 60 + m


def current_greg_minutes(dt=None):
    dt = dt or now_eth()
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=ETHIOPIA_TZ)
    else:
        dt = dt.astimezone(ETHIOPIA_TZ)
    return dt.hour * 60 + dt.minute


def shift_window(shift_key, dt=None):
    now_min = current_greg_minutes(dt)
    s = SHIFTS[shift_key]
    active = parse_hm(s["active_from"])
    late = parse_hm(s["late_after"])
    close = parse_hm(s["close"])
    return now_min >= active, now_min >= close, now_min >= late


def shift_options(day_type):
    if day_type == DAY_TYPES[0]:
        return list(SHIFTS.keys())
    return list(SHIFTS.keys())


def shift_display(key):
    s = SHIFTS[key]
    return f"{key} — {s['label']} | Gregorian {s['greg']}"



def ensure_messages_schema(conn):
    cur = conn.cursor()
    cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='messages'")
    if cur.fetchone() is None:
        cur.execute("CREATE TABLE messages (id INTEGER PRIMARY KEY AUTOINCREMENT, sender TEXT, recipient TEXT, message_text TEXT, timestamp TEXT, is_read INTEGER DEFAULT 0)")
    else:
        cols={row[1] for row in cur.execute("PRAGMA table_info(messages)").fetchall()}
        if "is_read" not in cols:
            cur.execute("ALTER TABLE messages ADD COLUMN is_read INTEGER DEFAULT 0")
    conn.commit()

def init_db():
    conn = db()
    c = conn.cursor()
    c.execute("""CREATE TABLE IF NOT EXISTS employees(
        emp_id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL, office TEXT, admin TEXT, dept TEXT,
        active INTEGER DEFAULT 1, phone TEXT DEFAULT '', email TEXT DEFAULT '', photo_name TEXT DEFAULT '',
        created_at TEXT DEFAULT '', updated_at TEXT DEFAULT ''
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS admins(
        username TEXT PRIMARY KEY, password TEXT NOT NULL, office TEXT, role TEXT,
        active INTEGER DEFAULT 1, created_at TEXT DEFAULT '', last_login TEXT DEFAULT ''
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS attendance(
        id INTEGER PRIMARY KEY AUTOINCREMENT, date_str TEXT, raw_date TEXT, name TEXT, emp_id TEXT,
        office TEXT, dept TEXT, admin TEXT, action_type TEXT, shift TEXT, status TEXT,
        leave_duration TEXT DEFAULT '-', late_reason TEXT DEFAULT '-', worked_hours REAL DEFAULT 0,
        overtime_hours REAL DEFAULT 0, day_type TEXT, signature TEXT DEFAULT '', timestamp TEXT,
        approval_status TEXT DEFAULT 'በማጣራት ላይ (Pending)', checkin_time TEXT DEFAULT '', checkout_time TEXT DEFAULT '',
        gregorian_time TEXT DEFAULT '', eth_time TEXT DEFAULT '', early_leave INTEGER DEFAULT 0,
        device_note TEXT DEFAULT '', approved_by TEXT DEFAULT ''
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS messages(
        id INTEGER PRIMARY KEY AUTOINCREMENT, sender TEXT, recipient TEXT, message_text TEXT,
        timestamp TEXT, is_read INTEGER DEFAULT 0
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS audit_logs(
        id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT, action TEXT, timestamp TEXT
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS holidays(
        id INTEGER PRIMARY KEY AUTOINCREMENT, holiday_date TEXT UNIQUE, holiday_name TEXT, calendar_type TEXT DEFAULT 'Gregorian', active INTEGER DEFAULT 1
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS leave_requests(
        id INTEGER PRIMARY KEY AUTOINCREMENT, emp_id TEXT, employee_name TEXT, leave_type TEXT,
        start_date TEXT, end_date TEXT, days REAL, reason TEXT, status TEXT DEFAULT 'Pending',
        requested_by TEXT DEFAULT '', approved_by TEXT DEFAULT '', created_at TEXT DEFAULT ''
    )""")
    c.execute("""CREATE TABLE IF NOT EXISTS app_settings(key TEXT PRIMARY KEY, value TEXT)""")

    # Migration for older attendance DBs.
    existing = {r[1] for r in c.execute("PRAGMA table_info(attendance)").fetchall()}
    additions = {
        "date_str":"TEXT DEFAULT ''", "raw_date":"TEXT DEFAULT ''", "name":"TEXT DEFAULT ''",
        "emp_id":"TEXT DEFAULT ''", "office":"TEXT DEFAULT ''", "dept":"TEXT DEFAULT ''", "admin":"TEXT DEFAULT ''",
        "action_type":"TEXT DEFAULT ''", "shift":"TEXT DEFAULT ''", "status":"TEXT DEFAULT ''",
        "leave_duration":"TEXT DEFAULT '-'", "late_reason":"TEXT DEFAULT '-'", "worked_hours":"REAL DEFAULT 0",
        "overtime_hours":"REAL DEFAULT 0", "day_type":"TEXT DEFAULT ''", "signature":"TEXT DEFAULT ''",
        "timestamp":"TEXT DEFAULT ''", "approval_status":"TEXT DEFAULT 'በማጣራት ላይ (Pending)'",
        "checkin_time":"TEXT DEFAULT ''", "checkout_time":"TEXT DEFAULT ''", "gregorian_time":"TEXT DEFAULT ''",
        "eth_time":"TEXT DEFAULT ''", "early_leave":"INTEGER DEFAULT 0", "device_note":"TEXT DEFAULT ''", "approved_by":"TEXT DEFAULT ''"
    }
    for col, typ in additions.items():
        if col not in existing:
            c.execute(f"ALTER TABLE attendance ADD COLUMN {col} {typ}")

    # ------------------------------------------------------------------
    # EMPLOYEE TABLE MIGRATION
    # Older attendance_system_v*.db files may not contain the `admin`
    # column.  The V4 application uses that column in INSERT/SELECT
    # statements, so it must be added before the default employees are
    # inserted.  SQLite ALTER TABLE safely adds missing columns without
    # deleting existing employee records.
    # ------------------------------------------------------------------
    emp_existing = {r[1] for r in c.execute("PRAGMA table_info(employees)").fetchall()}
    employee_additions = {
        "admin": "TEXT DEFAULT ''",
        "dept": "TEXT DEFAULT ''",
        "office": "TEXT DEFAULT ''",
        "active": "INTEGER DEFAULT 1",
        "phone": "TEXT DEFAULT ''",
        "email": "TEXT DEFAULT ''",
        "photo_name": "TEXT DEFAULT ''",
        "created_at": "TEXT DEFAULT ''",
        "updated_at": "TEXT DEFAULT ''",
    }
    for col, typ in employee_additions.items():
        if col not in emp_existing:
            c.execute(f"ALTER TABLE employees ADD COLUMN {col} {typ}")

    # Refresh the schema after ALTER TABLE statements.
    emp_existing = {r[1] for r in c.execute("PRAGMA table_info(employees)").fetchall()}

    # If an older database already contains employees but their admin
    # field is empty, restore it from the V4 master employee list by ID
    # or name.  Existing records are never deleted.
    if "admin" in emp_existing:
        for name, info in DEFAULT_EMPLOYEES.items():
            c.execute(
                "UPDATE employees SET admin=? WHERE (emp_id=? OR name=?) AND (admin IS NULL OR TRIM(admin)='')",
                (info["admin"], info["id"], name),
            )

    # Populate empty department/office fields from the V4 master list
    # where a matching employee is available.
    if "dept" in emp_existing and "office" in emp_existing:
        for name, info in DEFAULT_EMPLOYEES.items():
            c.execute(
                "UPDATE employees SET office=COALESCE(NULLIF(TRIM(office),''),?), dept=COALESCE(NULLIF(TRIM(dept),''),?) WHERE (emp_id=? OR name=?)",
                (info["office"], info["dept"], info["id"], name),
            )

    adm_existing = {r[1] for r in c.execute("PRAGMA table_info(admins)").fetchall()}
    for col, typ in {"active":"INTEGER DEFAULT 1", "created_at":"TEXT DEFAULT ''", "last_login":"TEXT DEFAULT ''"}.items():
        if col not in adm_existing:
            c.execute(f"ALTER TABLE admins ADD COLUMN {col} {typ}")

    now = now_eth().isoformat(timespec="seconds")
    defaults = [
        ("superadmin", "super08password", "ሁሉም ቢሮዎች", "ዋና አድሚን (Super Admin)"),
        ("admin_office1", "pass123office1", "ቢሮ ቁጥር 01 (የሲቪል ምዝገባ እና የነዋሪነት አገልግሎት)", "ቢሮ 01 አድሚን"),
    ]
    for username, password, office, role in defaults:
        row = c.execute("SELECT username FROM admins WHERE username=?", (username,)).fetchone()
        if not row:
            c.execute("INSERT INTO admins(username,password,office,role,created_at) VALUES(?,?,?,?,?)", (username, hash_password(password), office, role, now))
    for name, info in DEFAULT_EMPLOYEES.items():
        c.execute("""INSERT OR IGNORE INTO employees(emp_id,name,office,admin,dept,active,created_at,updated_at)
                     VALUES(?,?,?,?,?,?,?,?)""", (info["id"], name, info["office"], info["admin"], info["dept"], 1, now, now))
    conn.commit(); conn.close()


def audit(user, action):
    try:
        conn=db(); conn.execute("INSERT INTO audit_logs(username,action,timestamp) VALUES(?,?,?)", (user, action, get_ethiopian_time())); conn.commit(); conn.close()
    except Exception:
        pass


