def safe_float(value, default=0.0):
    """Safely convert an attendance numeric value to float."""
    if value is None:
        return default
    try:
        if isinstance(value, (int, float)):
            return float(value)
        text_value = str(value).strip()
        if not text_value:
            return default
        return float(text_value)
    except (ValueError, TypeError):
        return default


